#[test]
fn test_optimize_constant_folding_addition() {
    let expr = IRNode::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(IRNode::IntLiteral(2)),
        right: Box::new(IRNode::IntLiteral(3)),
    };

    let optimized = expr.fold_constants();
    assert_eq!(optimized, IRNode::IntLiteral(5));
}

#[test]
fn test_optimize_constant_folding_multiplication() {
    let expr = IRNode::BinaryOp {
        op: "Star".to_string(),
        left: Box::new(IRNode::IntLiteral(6)),
        right: Box::new(IRNode::IntLiteral(7)),
    };

    let optimized = expr.fold_constants();
    assert_eq!(optimized, IRNode::IntLiteral(42));
}

#[test]
fn test_optimize_constant_folding_nested() {
    let expr = IRNode::BinaryOp {
        op: "Plus".to_string(),
        left: Box::new(IRNode::BinaryOp {
            op: "Star".to_string(),
            left: Box::new(IRNode::IntLiteral(2)),
            right: Box::new(IRNode::IntLiteral(3)),
        }),
        right: Box::new(IRNode::IntLiteral(4)),
    };

    let optimized = expr.fold_constants();
    assert_eq!(optimized, IRNode::IntLiteral(10));
}

#[test]
fn test_optimize_dead_code_elimination() {
    let block = IRNode::Block(vec![
        IRNode::Assign {
            name: "unused".to_string(),
            value: Box::new(IRNode::IntLiteral(42)),
        },
        IRNode::IntLiteral(1),
    ]);

    let optimized = block.eliminate_dead_code();
    match optimized {
        IRNode::Block(nodes) => {
            assert_eq!(nodes.len(), 1);
        }
        _ => panic!("Expected Block"),
    }
}

#[test]
fn test_optimize_unused_variable_removed() {
    let block = IRNode::Block(vec![
        IRNode::Assign {
            name: "temp".to_string(),
            value: Box::new(IRNode::IntLiteral(99)),
        },
        IRNode::Assign {
            name: "result".to_string(),
            value: Box::new(IRNode::IntLiteral(42)),
        },
        IRNode::Variable("result".to_string()),
    ]);

    let optimized = block.eliminate_dead_code();
    match optimized {
        IRNode::Block(nodes) => {
            // temp is unused, should be removed
            assert!(nodes.iter().all(|n| {
                if let IRNode::Assign { name, .. } = n {
                    name != "temp"
                } else {
                    true
                }
            }));
        }
        _ => panic!("Expected Block"),
    }
}

