// 값 표현 (Value Representation)
// Phase 5: 런타임

use std::collections::HashMap;
use std::fmt;
use crate::ir::IRNode;

/// 런타임 값 표현
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    /// 정수 (64-bit)
    Integer(i64),

    /// 실수 (64-bit)
    Float(f64),

    /// 문자열
    String(String),

    /// 불린
    Boolean(bool),

    /// 배열
    Array(Vec<Value>),

    /// 튜플
    Tuple(Vec<Value>),

    /// 함수
    Function {
        name: String,
        params: Vec<String>,
        body: Vec<IRNode>,
    },

    /// 빈 값
    None,
}

impl Value {
    /// 값의 타입 이름을 반환합니다
    pub fn type_name(&self) -> &str {
        match self {
            Value::Integer(_) => "integer",
            Value::Float(_) => "float",
            Value::String(_) => "string",
            Value::Boolean(_) => "boolean",
            Value::Array(_) => "array",
            Value::Tuple(_) => "tuple",
            Value::Function { .. } => "function",
            Value::None => "none",
        }
    }

    /// 값을 정수로 변환합니다
    pub fn to_integer(&self) -> Option<i64> {
        match self {
            Value::Integer(n) => Some(*n),
            Value::Float(f) => Some(*f as i64),
            Value::Boolean(b) => Some(if *b { 1 } else { 0 }),
            _ => None,
        }
    }

    /// 값을 실수로 변환합니다
    pub fn to_float(&self) -> Option<f64> {
        match self {
