    pub fn len(&self) -> Option<usize> {
        match self {
            Value::Array(arr) => Some(arr.len()),
            Value::String(s) => Some(s.len()),
            Value::Tuple(t) => Some(t.len()),
            _ => None,
        }
    }

    /// 배열에 요소 추가
    pub fn push(&mut self, value: Value) -> Result<(), String> {
        match self {
